548	static void configure_pin(uint8_t gpio_pin, uint8_t sdio_pin,
549	                          gpio_pinattr_t attr)
550	{
551	  esp32s3_configgpio(gpio_pin, attr);
552	
553	  if (attr & INPUT)
554	    {
555	      esp32s3_gpio_matrix_in(gpio_pin, sdio_pin, false);
556	    }
557	
558	  if (attr & OUTPUT)
559	    {
560	      esp32s3_gpio_matrix_out(gpio_pin, sdio_pin, false, false);
561	    }
562	}
