577	
578	static void esp32s3_enable_ints(struct esp32s3_dev_s *priv)
579	{
580	  uint32_t regval;
581	
582	#ifdef CONFIG_ESP32S3_SDMMC_DMA
583	  mcinfo("waitmask=%04lx xfrmask=%04lx dmamask=%04lx RINTSTS=%08lx\n",
584	         (unsigned long)priv->waitmask, (unsigned long)priv->xfrmask,
585	         (unsigned long)priv->dmamask,
586	         (unsigned long)esp32s3_getreg(ESP32S3_SDMMC_RINTSTS));
587	#else
588	  mcinfo("waitmask=%04lx xfrmask=%04lx RINTSTS=%08lx\n",
589	         (unsigned long)priv->waitmask, (unsigned long)priv->xfrmask,
590	         (unsigned long)esp32s3_getreg(ESP32S3_SDMMC_RINTSTS));
591	#endif
592	
593	  /* Enable SDMMC interrupts */
594	
595	  regval = priv->xfrmask | priv->waitmask | SDCARD_INT_CDET;
596	  esp32s3_putreg(regval, ESP32S3_SDMMC_INTMASK);
597	}
